-- 엄배송 샘플 데이터 (계정 4개, 상품, 주문, 문의, 구매평 등)
-- schema.sql 실행 후 SQL Editor 에서 실행하세요. 여러 번 실행해도 안전합니다.
-- 주의: 샘플 관리자(admin / admin1234)는 공개 전에 비밀번호를 꼭 바꾸세요.

create extension if not exists pgcrypto with schema extensions;

insert into auth.users (instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,recovery_token,email_change_token_new,email_change)
select '00000000-0000-0000-0000-000000000000','a0000000-0000-4000-8000-000000000001','authenticated','authenticated','admin@sellerport.app',extensions.crypt('admin1234',extensions.gen_salt('bf')),now(),'{"provider":"email","providers":["email"]}'::jsonb,'{}'::jsonb,now(),now(),'','','',''
where not exists (select 1 from auth.users where email='admin@sellerport.app');
insert into auth.identities (id,user_id,identity_data,provider,provider_id,last_sign_in_at,created_at,updated_at)
select gen_random_uuid(),'a0000000-0000-4000-8000-000000000001','{"sub":"a0000000-0000-4000-8000-000000000001","email":"admin@sellerport.app","email_verified":true}'::jsonb,'email','admin@sellerport.app',now(),now(),now()
where exists (select 1 from auth.users where id='a0000000-0000-4000-8000-000000000001') and not exists (select 1 from auth.identities where provider='email' and provider_id='admin@sellerport.app');
