-- 회원 정보 (이미 있는 같은 아이디의 계정은 그대로 두고, 샘플 계정이 없을 때만 추가)
insert into public.profiles (id,login_id,name,phone,role,created_at) select u.id,'admin','관리자','010-0000-0000','admin','2026-11-01T09:00:00Z' from auth.users u where u.email='admin@sellerport.app' on conflict do nothing;
