-- 상품 (옵션, 입력 항목, 상세 페이지 포함)
select public._save_product('{"id":"s-shopee","images":["img-s-shopee"],"cat":"shopee","type":"register","name":"쇼피 배송등록","desc":"쇼피 주문번호를 입력하면 한 건씩 배송을 접수합니다.","price":2000,"sale":1900,"unit":"건","best":true,"soldout":false,"order":1,"pointRate":1,"hideQty":true,"options":[{"id":"g1","name":"옵션","required":true,"placeholder":"옵션 (선택)","choices":[{"label":"옵션없음","add":0},{"label":"박스교체","add":300},{"label":"화장품사은품추가","add":300},{"label":"맥심모카골드추가","add":300},{"label":"마스크팩추가","add":500},{"label":"이니스프리마스크팩","add":1000},{"label":"대형포장","add":500}]}],"fields":[{"id":"f1","label":"택배운송장번호","type":"text","required":true,"unique":true,"placeholder":"필수입력"},{"id":"f2","label":"제품명/색상/수량","type":"text","required":true,"placeholder":"필수입력"},{"id":"f3","label":"상품url","type":"text","required":true,"placeholder":"필수입력"},{"id":"f4","label":"배송요청사항","type":"text","required":true,"placeholder":"필수입력"},{"id":"f5","label":"택배사명(예:대한통운)","type":"select","required":true,"options":["CJ대한통운","한진택배","롯데택배","우체국택배","로젠택배","경동택배","대신택배","GS25편의점택배","CU편의점택배","기타"],"placeholder":"택배사명(예:대한통운) (필수)"},{"id":"f6","label":"송장 파일 업로드(PDF)","type":"file","required":true,"stage":"order","help":"마켓에서 받은 waybill 파일"}],"detail":[{"t":"h","text":"배송등록 사용 방법"},{"t":"p","text":"1. 해외 마켓 주문이 들어온 상품을 국내 쇼핑몰에서 구매합니다.\n2. 이 페이지에서 택배 운송장번호, 제품명/색상/수량, 상품 URL, 배송요청사항, 택배사를 입력합니다.\n3. 옵션을 고른 뒤 구매하기를 누르고, 다음 단계에서 마켓 송장 파일(PDF)을 올립니다.\n4. 결제를 마치면 배송지에 도착한 상품을 확인해 접수 후 발송합니다."},{"t":"note","text":"운송장번호는 배대지로 도착할 상품의 번호를 적어 주세요. 같은 번호는 한 번만 접수됩니다. 부분 배송이 필요하면 배송요청사항에 적어 주세요."},{"t":"h","text":"옵션 안내"},{"t":"p","text":"옵션없음 (+0원)\n도착한 상품을 완충재로 감싸 그대로 발송합니다.\n\n박스교체 (+300원)\n상품에 맞는 박스로 바꿔 다시 포장해 발송합니다.\n\n화장품사은품추가 (+300원)\n샘플 화장품을 무작위로 함께 넣어 보냅니다.\n\n맥심모카골드추가 (+300원)\n커피 스틱을 함께 넣어 보냅니다.\n\n마스크팩추가 (+500원)\n마스크팩을 함께 넣어 보냅니다.\n\n이니스프리마스크팩 (+1,000원)\n해당 브랜드 마스크팩을 함께 넣어 보냅니다.\n\n대형포장 (+500원)\n가로+세로+높이 합이 1m 이상인 상품일 때 선택해 주세요."},{"t":"note","text":"옵션이 필요 없으면 옵션없음을 선택해 주세요. 입력 후 구매하기를 누르면 추가 정보 입력(송장 업로드)과 결제 단계로 이동합니다."}]}'::jsonb);
