insert into public.notices (id,title,body,created_at) values ('n1','엄배송 오픈 안내','쇼피·큐텐 배송등록을 시작합니다. 주문번호와 송장 파일만 준비해 주세요.','2026-11-20T09:00:00Z'),('n2','이용 시간 안내','접수 확인은 평일 10시~18시에 처리됩니다. 주말 접수는 다음 영업일에 확인합니다.','2026-11-21T09:00:00Z') on conflict (id) do update set title=excluded.title,body=excluded.body;
insert into public.site_settings (key,value) values ('bank','국민은행'),('account','000000-00-000000'),('holder','엄배송'),('banner','주문번호만 보내세요. 나머지는 엄배송이 끝까지 책임집니다.'),('bizName','엄배송'),('ceo','홍길동'),('tel','010-0000-0000'),('hours','평일 10:00~18:00') on conflict (key) do update set value=excluded.value;

