insert into public.wallets (user_id,balance,updated_at) select u.id,v.b,now() from (values ('buyer01',12000),('buyer02',500),('buyer03',0)) v(l,b) join public.profiles u on u.login_id=v.l on conflict (user_id) do nothing;
insert into public.wallet_log (user_id,delta,reason,at) select u.id,v.d,v.r,v.t::timestamptz from (values ('buyer01',12000,'적립금 충전 샘플','2026-11-20T00:00:00Z'),('buyer02',500,'가입 적립','2026-11-19T00:00:00Z')) v(l,d,r,t) join public.profiles u on u.login_id=v.l where not exists (select 1 from public.wallet_log w where w.user_id=u.id);

